export function chatFirstActiveSurface({ activeAppId, activeTab, }) {
    if (activeTab !== undefined)
        return { kind: "nav", tab: activeTab };
    if (activeAppId !== undefined)
        return { kind: "app", appId: activeAppId };
    return undefined;
}
export function chatFirstAppIconState(surface, appId) {
    if (!surface)
        return { isActive: false, isInactive: false };
    const isActive = surface.kind === "app" && surface.appId === appId;
    return { isActive, isInactive: !isActive };
}
export function chatFirstNavTabActive(surface, tab) {
    return surface?.kind === "nav" && surface.tab === tab;
}
